-- C08 | age on a reference date
-- Question : What is the total revenue excluding VAT, in euro cents, generated by customers who are exactly 25 years old on the reference date 2026-09-24 (all their orders)?
--
-- Auteur          : Ayoub LAMCHICHI
-- Vérifié par     : hechmi Chemli
-- Vérification    : recalcul Python sur les CSV (âge révolu) = 605580.

SELECT COALESCE(SUM(o.quantity_product * p.price), 0) AS revenue_cents
FROM orders o
JOIN product p USING (product_id)
JOIN customers c USING (customer_id)
WHERE (
        CAST(strftime('%Y', '2026-09-24') AS INT)
      - CAST(strftime('%Y', c.birth_date) AS INT)
      - (strftime('%m-%d', '2026-09-24') < strftime('%m-%d', c.birth_date))
      ) = 25;

-- Résultat : revenue_cents = 605580
